import{_ as e,o,c as a,a2 as r}from"./chunks/framework.CPHNBVkq.js";const g=JSON.parse('{"title":"Welcome to Corbi","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),s={name:"guide/index.md"};function n(i,t,d,h,l,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="welcome-to-corbi" tabindex="-1">Welcome to Corbi <a class="header-anchor" href="#welcome-to-corbi" aria-label="Permalink to &quot;Welcome to Corbi&quot;">​</a></h1><p>Corbi is your personal assistant for staying on top of what&#39;s happening across your business — without drowning in noise. Instead of checking a dozen systems or scrolling through everything, you tell Corbi what you care about and it brings the relevant updates to you.</p><p>This guide walks you through everything Corbi can do, from reading your feed to setting up channels, chatting with the assistant, and creating tasks.</p><h2 id="what-you-can-do-with-corbi" tabindex="-1">What you can do with Corbi <a class="header-anchor" href="#what-you-can-do-with-corbi" aria-label="Permalink to &quot;What you can do with Corbi&quot;">​</a></h2><ul><li><strong>Read your Pulse feed</strong> — a single feed of business updates filtered to what matters to you.</li><li><strong>Set up channels</strong> — control exactly which updates show up in your feed.</li><li><strong>Chat with Corbi</strong> — ask questions and complete guided tasks through a conversation.</li><li><strong>Create tasks</strong> — describe what you need in plain language and review a draft before it runs.</li><li><strong>Get a daily summary</strong> — receive one email a day, at a time you choose, recapping your feed.</li></ul><div class="tip custom-block"><p class="custom-block-title">New to Corbi?</p><p>Start with <a href="./getting-started.html">Getting Started</a> for a quick tour, then set up your first channel so your Pulse feed has something to show.</p></div><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p>You&#39;ll see these words throughout the guide and the app. Here&#39;s what they mean.</p><table tabindex="0"><thead><tr><th>Term</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Pulse</strong></td><td>Your feed of business updates. Each item is a &quot;Pulse item.&quot;</td></tr><tr><td><strong>Channel</strong></td><td>A saved filter that decides which updates appear in your feed. You can have several.</td></tr><tr><td><strong>Category</strong></td><td>The kind of business event a channel follows (for example, Sales, HR, Finance).</td></tr><tr><td><strong>Channel Scope</strong></td><td>How wide a channel reaches — <strong>Broad</strong> (more updates) or <strong>Narrow</strong> (more focused).</td></tr><tr><td><strong>Channel Tags</strong></td><td>Specific things within a category — like a particular project or person — used to focus a channel further.</td></tr><tr><td><strong>Daily Summary</strong></td><td>A once-a-day email recap of your Pulse feed, sent at a time you pick.</td></tr><tr><td><strong>Chat</strong></td><td>A conversation with Corbi. Some replies include a <strong>chat form</strong> to fill in.</td></tr><tr><td><strong>Chat form</strong></td><td>A short interactive form that appears in a conversation to collect details from you.</td></tr><tr><td><strong>Task</strong></td><td>Something you ask Corbi to do, described in plain language. Tasks have <strong>draft</strong> and <strong>live</strong> versions.</td></tr></tbody></table><h2 id="how-this-guide-is-organized" tabindex="-1">How this guide is organized <a class="header-anchor" href="#how-this-guide-is-organized" aria-label="Permalink to &quot;How this guide is organized&quot;">​</a></h2><ul><li><strong>Getting Started</strong> — sign in and find your way around.</li><li><strong>Staying Updated</strong> — the Pulse feed and how to set up channels.</li><li><strong>Working with Corbi</strong> — chatting and creating tasks.</li><li><strong>Preferences</strong> — notifications, the daily summary, and settings.</li><li><strong>Help</strong> — answers to common questions.</li></ul><div class="info custom-block"><p class="custom-block-title">A note on what you&#39;ll see</p><p>Corbi shows the features your account has access to. Depending on how your organization has set things up, you may not see Chat, Pulse, or Tasks in your navigation. If something described here isn&#39;t visible to you, check with your administrator.</p></div>',12)])])}const p=e(s,[["render",n]]);export{g as __pageData,p as default};
